def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Implementing the Kondener's Model for log10(|ID|/A) in terms of |VGS| and |VDS|."""
    Vp, S = parameters
    return log10((gate_voltage_abs - Vp) * (drain_voltage_abs - Vp) / (S * S))
